#!/usr/bin/env python3
"""Product-owned consumer bootstrap; generated by sc-lint init --just."""

import sys

if sys.version_info < (3, 9):
    print("setup: Python 3.9 or newer is required (CLI.SC_LINT_PYTHON_UNAVAILABLE)", file=sys.stderr)
    sys.exit(1)

import hashlib
import json
import os
from pathlib import Path
import platform
import re
import shutil
import subprocess
import tarfile
import tempfile
import urllib.error
import urllib.request
import venv
import zipfile

USAGE = ("usage: .sc-lint/bootstrap.py setup --config sc-lint.toml [--dry-run]; "
         ".sc-lint/bootstrap.py upgrade --config sc-lint.toml [--check] [--dry-run]; "
         ".sc-lint/bootstrap.py lint [selector] [host|all|linux|macos|windows] --config sc-lint.toml; "
         ".sc-lint/bootstrap.py lint [--fail-fast] [selector] [host|all|linux|macos|windows] --config sc-lint.toml; "
         ".sc-lint/bootstrap.py test [--fail-fast|--list] [selector [args...]] --config sc-lint.toml; "
         ".sc-lint/bootstrap.py exec [--config sc-lint.toml] -- <argv...>")


def fail(message, code):
    print(message, file=sys.stderr)
    raise SystemExit(code)


def usage():
    fail(USAGE, 2)


def parse(argv):
    if not argv or argv[0] not in ("setup", "lint", "test", "upgrade", "exec"):
        usage()
    operation, rest = argv[0], argv[1:]
    if operation == "exec":
        config = None
        if rest[:1] == ["--config"]:
            if len(rest) < 2 or not rest[1]:
                usage()
            config, rest = rest[1], rest[2:]
        if len(rest) < 2 or rest[0] != "--":
            usage()
        return operation, config, [], [], rest[1:]
    config, flags, positional = None, [], []
    while rest:
        token, rest = rest[0], rest[1:]
        if operation == "test" and positional:
            # Everything after the test selector is forwarded verbatim.
            positional.append(token)
        elif token == "--config":
            if config is not None or not rest or not rest[0]:
                usage()
            config, rest = rest[0], rest[1:]
        elif token == "--dry-run" and operation == "setup" and token not in flags:
            flags.append(token)
        elif token in ("--check", "--dry-run") and operation == "upgrade" and token not in flags:
            flags.append(token)
        elif (token == "--fail-fast" and operation in ("lint", "test")
              or token == "--list" and operation == "test") and token not in flags:
            flags.append(token)
        elif token.startswith("--"):
            usage()
        else:
            positional.append(token)
    maximum = {"setup": 0, "upgrade": 0, "lint": 2, "test": len(positional)}[operation]
    if not config or len(positional) > maximum or (operation == "lint" and len(positional) == 2 and not positional[1]):
        usage()
    if "--list" in flags and (positional or "--fail-fast" in flags):
        usage()
    return operation, config, flags, positional, []


def run(argv, **kwargs):
    try:
        command = [str(item) for item in argv]
        # Windows otherwise searches the parent Python directory before PATH.
        command[0] = shutil.which(command[0]) or command[0]
        return subprocess.run(command, check=False, **kwargs).returncode
    except OSError as error:
        print(f"{argv[0]}: {error}", file=sys.stderr)
        return 127


def default_install_directory(environ, home_directory, windows):
    # Mirrors the native installer: SC_LINT_INSTALL_DIR, else the platform data
    # directory (%APPDATA% on Windows, XDG_DATA_HOME elsewhere) plus sc-lint/bin.
    # home_directory is a callable so the home lookup runs only when no override
    # supplies the directory; a host without a home still honours the override.
    if environ.get("SC_LINT_INSTALL_DIR"):
        return Path(environ["SC_LINT_INSTALL_DIR"])
    if windows:
        data_dir = Path(environ.get("APPDATA") or home_directory() / "AppData" / "Roaming")
    else:
        data_dir = Path(environ.get("XDG_DATA_HOME") or home_directory() / ".local" / "share")
    return data_dir / "sc-lint" / "bin"


def managed_path():
    windows = os.name == "nt"
    try:
        directory = default_install_directory(os.environ, Path.home, windows)
    except (RuntimeError, KeyError):
        # Path.home() raises RuntimeError when no home can be determined, and KeyError
        # on Python 3.9 when the user has no passwd entry. The native installer
        # reports the same condition with this code.
        fail(
            "sc-lint install directory is unavailable: neither SC_LINT_INSTALL_DIR, APPDATA, "
            "XDG_DATA_HOME nor a home directory was available; set SC_LINT_INSTALL_DIR to a "
            "writable directory and rerun (CLI.SC_LINT_INSTALL_PERMISSION_DENIED)",
            4,
        )
    return directory / ("sc-lint.exe" if windows else "sc-lint")


def resolve_binary(managed):
    override = os.environ.get("SC_LINT_BIN")
    resolved = shutil.which(override) if override else None
    if resolved:
        return Path(os.path.abspath(resolved)), True
    if managed.is_file():
        return managed, False
    resolved = shutil.which("sc-lint")
    return (Path(os.path.abspath(resolved)), False) if resolved else (None, False)


def minimum_version(config):
    try:
        text = Path(config).read_text(encoding="utf-8")
    except OSError:
        text = ""
    match = re.search(r'^\s*minimum_version\s*=\s*"([^"]+)"', text, re.MULTILINE)
    if not match:
        fail(f"setup: could not read minimum_version from {config} (CLI.SC_LINT_CONFIG_MALFORMED)", 3)
    return match.group(1)


def release_target():
    key = (platform.system(), platform.machine().lower())
    targets = {("Linux", "x86_64"): ("x86_64-unknown-linux-gnu", "tar.gz"),
               ("Linux", "aarch64"): ("aarch64-unknown-linux-gnu", "tar.gz"),
               ("Linux", "arm64"): ("aarch64-unknown-linux-gnu", "tar.gz"),
               ("Darwin", "x86_64"): ("x86_64-apple-darwin", "tar.gz"),
               ("Darwin", "arm64"): ("aarch64-apple-darwin", "tar.gz"),
               ("Windows", "amd64"): ("x86_64-pc-windows-msvc", "zip"),
               ("Windows", "arm64"): ("aarch64-pc-windows-msvc", "zip"),
               ("Windows", "aarch64"): ("aarch64-pc-windows-msvc", "zip"),
               ("Windows", "x86_64"): ("x86_64-pc-windows-msvc", "zip")}
    if key not in targets:
        fail(f"setup: no verified sc-lint release for {key[0]}/{key[1]} (CLI.SC_LINT_INSTALL_UNSUPPORTED_PLATFORM)", 4)
    return targets[key]


def install_release(config, operation, flags):
    version = minimum_version(config)
    target, extension = release_target()
    archive = f"sc-lint_{version}_{target}.{extension}"
    base = os.environ.get("SC_LINT_RELEASE_BASE_URL", "https://github.com/randlee/sc-lint/releases/download").rstrip("/")
    url = f"{base}/v{version}"
    try:
        with urllib.request.urlopen(f"{url}/checksums.txt", timeout=60) as response:
            checksums = response.read().decode("utf-8")
        expected = None
        for line in checksums.splitlines():
            parts = line.split()
            if len(parts) >= 2 and parts[1].lstrip("*") == archive:
                expected = parts[0]
                break
        if not expected:
            fail(f"setup: checksum manifest did not contain {archive} (CLI.SC_LINT_RELEASE_UNAVAILABLE)", 4)
        with urllib.request.urlopen(f"{url}/{archive}", timeout=120) as response:
            content = response.read()
    except (OSError, ValueError, UnicodeError) as error:
        fail(f"setup: could not download release: {error} (CLI.SC_LINT_RELEASE_UNAVAILABLE)", 4)
    if hashlib.sha256(content).hexdigest().lower() != expected.lower():
        fail(f"setup: SHA-256 verification failed for {archive} (CLI.SC_LINT_RELEASE_CHECKSUM_MISMATCH)", 4)
    binary_name = "sc-lint.exe" if os.name == "nt" else "sc-lint"
    names = [binary_name, f"sc-lint_{version}_{target}/bin/{binary_name}"]
    with tempfile.TemporaryDirectory(prefix="sc-lint-bootstrap-") as temporary:
        archive_path = Path(temporary) / archive
        archive_path.write_bytes(content)
        try:
            if extension == "zip":
                with zipfile.ZipFile(archive_path) as package:
                    name = next((name for name in names if name in package.namelist()), None)
                    payload = package.read(name) if name else None
            else:
                with tarfile.open(archive_path, "r:gz") as package:
                    members = {member.name: member for member in package.getmembers() if member.isfile()}
                    name = next((name for name in names if name in members), None)
                    stream = package.extractfile(members[name]) if name else None
                    payload = stream.read() if stream else None
            if payload is None:
                fail(f"setup: release archive did not contain {binary_name} (CLI.SC_LINT_RELEASE_UNAVAILABLE)", 4)
            launcher = Path(temporary) / binary_name
            launcher.write_bytes(payload)
            launcher.chmod(0o755)
            return run([launcher, "--config", config, operation, *flags])
        except (OSError, tarfile.TarError, zipfile.BadZipFile) as error:
            fail(f"setup: could not extract {archive}: {error} (CLI.SC_LINT_RELEASE_UNAVAILABLE)", 4)


def venv_directory(config):
    return Path(config).resolve().parent / ".sc-lint" / "venv"


def venv_scripts(config):
    return venv_directory(config) / ("Scripts" if os.name == "nt" else "bin")


def activate(binary, config):
    os.environ["SC_LINT_BIN"] = str(binary)
    os.environ["PATH"] = os.pathsep.join([str(Path(binary).parent), str(venv_scripts(config)), os.environ.get("PATH", "")])


class Bootstrap:
    def __init__(self, config):
        self.config = config
        self.managed = managed_path()
        self.directory = venv_directory(config)
        scripts = venv_scripts(config)
        self.python = scripts / ("python.exe" if os.name == "nt" else "python3")
        self.install_input = self.directory.parent / "install.json"
        self.binary = None

    def ensure(self, flags):
        self.binary, override = resolve_binary(self.managed)
        if not self.binary:
            status = install_release(self.config, "setup", flags)
            if status:
                return status
            self.binary = self.managed
        status = run([self.binary, "--config", self.config, "compatibility", "check", "--binary", self.binary])
        if status:
            if override or "--check" in flags or "--dry-run" in flags:
                status = run([self.binary, "--config", self.config, "setup", *flags])
            else:
                status = install_release(self.config, "setup", flags)
                if not status:
                    self.binary = self.managed
            if status:
                return status
        return 0

    def provision_venv(self, mode):
        version = minimum_version(self.config)
        probe = "import sys, sc_lint; p=lambda v:tuple(int(x) for x in v.split('+')[0].split('.')[:3]); sys.exit(0 if p(sc_lint.__version__) >= p(sys.argv[1]) else 1)"
        if self.python.is_file() and run([self.python, "-c", probe, version], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL) == 0:
            return 0
        if mode == "check":
            print(f"setup: {self.directory} does not provide sc-lint>={version} (CLI.SC_LINT_PYTHON_UNAVAILABLE)", file=sys.stderr)
            return 4
        if mode == "dry-run":
            print(f"setup: would install sc-lint=={version} into {self.directory}")
            return 0
        try:
            if not self.python.is_file():
                venv.create(self.directory, with_pip=True)
        except (OSError, subprocess.SubprocessError) as error:
            print(f"setup: could not create {self.directory}: {error} (CLI.SC_LINT_PYTHON_UNAVAILABLE)", file=sys.stderr)
            return 4
        wheel_dir = os.environ.get("SC_LINT_WHEEL_DIR")
        options = ["--no-index", "--find-links", wheel_dir] if wheel_dir else []
        if run([self.python, "-m", "pip", "install", "--quiet", "--disable-pip-version-check", *options, f"sc-lint=={version}"]):
            print(f"setup: could not install sc-lint=={version} into {self.directory} (CLI.SC_LINT_PYTHON_UNAVAILABLE)", file=sys.stderr)
            return 4
        return 0

    def provision_tools(self, mode):
        if not self.install_input.exists():
            return 0
        try:
            data = json.loads(self.install_input.read_text(encoding="utf-8"))
            tools = data.get("tools", {}) if isinstance(data, dict) else None
            empty = {"cargo": {}, "rustup_targets": []}
            declared = not isinstance(tools, dict) or any(key not in empty or tools[key] != empty[key] for key in tools)
        except (OSError, ValueError):
            declared = True
        if not declared:
            return 0
        if not self.python.is_file() or run([self.python, "-c", "import sc_lint.setup_tools"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL):
            if mode == "install":
                print(f"setup: {self.install_input} declares tools, but the sc-lint wheel in {self.directory} does not provide sc_lint.setup_tools (SETUP_TOOLS.INSPECTION_UNAVAILABLE); raise minimum_version, then run just setup", file=sys.stderr)
            else:
                print(f"setup: {self.install_input} declares tools that cannot be inspected because sc_lint.setup_tools is unavailable in {self.directory} (SETUP_TOOLS.INSPECTION_UNAVAILABLE); run just setup", file=sys.stderr)
            return 4
        return run([self.python, "-m", "sc_lint.setup_tools", "--config", self.config, *([] if mode == "install" else ["--check"])])


def main(argv=None):
    operation, config, flags, positional, command = parse(sys.argv[1:] if argv is None else argv)
    if operation == "exec":
        managed = managed_path()
        override = os.environ.get("SC_LINT_BIN")
        binary = shutil.which(override) if override else str(managed)
        if not binary or not Path(binary).is_file() or (os.name != "nt" and not os.access(binary, os.X_OK)):
            fail(f"sc-lint binary is unavailable at {override or managed}; run just setup", 1)
        binary = os.path.abspath(binary)
        activate(binary, config or "sc-lint.toml")
        if command[0] == "sc-lint":
            command = [binary, *(["--config", config] if config else []), *command[1:]]
        return run(command)
    bootstrap = Bootstrap(config)
    mode = "check" if "--check" in flags else "dry-run" if "--dry-run" in flags else "install"
    if operation == "upgrade":
        bootstrap.binary, override = resolve_binary(bootstrap.managed)
        if not bootstrap.binary:
            return install_release(config, "upgrade", flags)
        compatible = run([bootstrap.binary, "--config", config, "compatibility", "check", "--binary", bootstrap.binary]) == 0
        if not compatible and not override and mode == "install":
            return install_release(config, "upgrade", flags)
        status = run([bootstrap.binary, "--config", config, "upgrade", *flags])
        return status or bootstrap.provision_venv(mode)
    status = bootstrap.ensure(flags if operation == "setup" else [])
    if status:
        return status
    if operation == "setup":
        status = run([bootstrap.binary, "--config", config, "setup", *flags])
        return status or bootstrap.provision_venv(mode) or bootstrap.provision_tools(mode)
    activate(bootstrap.binary, config)
    status = bootstrap.provision_venv("install")
    if status:
        return status
    if operation == "test":
        return run([bootstrap.binary, "test", "--config", config, *flags, *positional])
    arguments = [bootstrap.binary, "lint", "--consumer", "--config", config, "ci"]
    if positional and positional[0]:
        arguments += ["--profile", positional[0]]
    if len(positional) == 2:
        arguments += ["--platform-scope", positional[1]]
    return run([*arguments, *flags])


if __name__ == "__main__":
    sys.exit(main())
